import {
  Group,
  Mesh,
  PlaneGeometry,
  Vector3,
  Color
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  uv,
  vec3,
  texture,
  uniform,
  mix,
  smoothstep,
  positionLocal,
  normalLocal
} from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  const timelines = [];

  // 1. STAGE BACKDROP (Designed for dark, gradient backdrop)
  const bgGeom = new PlaneGeometry(7.5, 6.0);
  const bgMat = new MeshBasicNodeMaterial();
  const stops = config.intent?.visualSpec?.colors?.gradientStops || [
    { at: 0.45, hex: "#0b0b1000" },
    { at: 1.0, hex: "#0b0b10eb" }
  ];
  const stopColor1 = new Color(stops[0].hex.slice(0, 7));
  const stopColor2 = new Color(stops[1].hex.slice(0, 7));

  // Vertical gradient shader using TSL
  const vUv = uv();
  bgMat.colorNode = mix(
    uniform(stopColor1),
    uniform(stopColor2),
    smoothstep(0.45, 1.0, vUv.y)
  );
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // 2. HERO PHOTO PLATE (parallax-plane)
  // Dimensions specified: 4.0w x 2.5h scene units
  const plateWidth = 4.0;
  const plateHeight = 2.5;
  const geometry = new PlaneGeometry(plateWidth, plateHeight, 128, 128);
  const material = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.4,
    transparent: true,
    opacity: 0.0 // Start at 0 for entrance animation
  });

  const plateMesh = new Mesh(geometry, material);
  group.add(plateMesh);

  // Load Image and Depth Map
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    material.map = tex;
    // Filmic grade pipeline simulation via TSL: high contrast, crushed blacks, slight desaturation except red
    material.colorNode = texture(tex).mul(1.12); // basic contrast lift
    material.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(depthMapUrl).then((depthTex) => {
    // Vertex displacement node for high-fidelity interactive physical depth
    const dispAmount = uniform(0.18);
    const depthVal = texture(depthTex).r;
    material.positionNode = positionLocal.add(normalLocal.mul(depthVal.mul(dispAmount)));
    material.needsUpdate = true;
  });

  // 3. CAPTION BLOCK & TEXT TYPOGRAPHY
  const captionBlock = new Group();
  captionBlock.position.set(-plateWidth / 2 + 0.5, -plateHeight / 2 + 0.5, 0.1);
  group.add(captionBlock);

  // Text values mapping from visualSpec / textContent
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textContentMap = {
    kicker: "NOVA ATELIER / GENEVA",
    headline: "Time, Machined.",
    body: "Every case begins as a single billet of 904L steel.",
    caption: "CALIBRE NA-01 / 72 HOUR RESERVE"
  };

  items.forEach(item => {
    if (item.text) {
      const lower = item.text.toLowerCase();
      if (lower.includes("geneva") || lower.includes("nova")) textContentMap.kicker = item.text;
      else if (lower.includes("time") || lower.includes("machined")) textContentMap.headline = item.text;
      else if (lower.includes("billet") || lower.includes("904l")) textContentMap.body = item.text;
      else if (lower.includes("calibre") || lower.includes("reserve")) textContentMap.caption = item.text;
    }
  });

  // Render using ctx.fontAtlas
  let currentY = 0;

  // Kicker (9px or scene scale ~0.09)
  const kickerObj = ctx.fontAtlas.createText(textContentMap.kicker, {
    fontSize: 48, // atlas size equivalent
    color: '#ff2a38', // Accent color
    align: 'left'
  });
  kickerObj.scale.setScalar(0.0018);
  kickerObj.position.set(0, currentY, 0);
  captionBlock.add(kickerObj);
  currentY -= 0.18;

  // Headline (Lora 34px or scene scale ~0.34)
  const headlineObj = ctx.fontAtlas.createText(textContentMap.headline, {
    fontSize: 120,
    color: '#e8ecf2', // secondary / paper
    align: 'left'
  });
  headlineObj.scale.setScalar(0.0028);
  headlineObj.position.set(0, currentY, 0);
  captionBlock.add(headlineObj);
  currentY -= 0.38;

  // Accent Hairline Bar: 0.75w x 0.02h, #ff2a38 emissive intensity 1.8
  const barGeom = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshBasicNodeMaterial({ color: 0xff2a38 });
  const barMesh = new Mesh(barGeom, barMat);
  barMesh.position.set(0.375, currentY, 0);
  captionBlock.add(barMesh);
  currentY -= 0.15;

  // Body (JetBrains Mono 13px or scene scale ~0.13)
  const bodyObj = ctx.fontAtlas.createText(textContentMap.body, {
    fontSize: 54,
    color: '#e8ecf2',
    align: 'left'
  });
  bodyObj.scale.setScalar(0.002);
  bodyObj.position.set(0, currentY, 0);
  captionBlock.add(bodyObj);
  currentY -= 0.22;

  // Caption (Atlas display bottom corner helper)
  const captionObj = ctx.fontAtlas.createText(textContentMap.caption, {
    fontSize: 40,
    color: '#8b8b9a',
    align: 'left'
  });
  captionObj.scale.setScalar(0.0015);
  captionObj.position.set(0, currentY, 0);
  captionBlock.add(captionObj);

  // 4. ANIMATION FLOW
  // Plate mount opacity 0 -> 1 over 500ms
  const tlPlate = gsap.to(material, {
    opacity: 1,
    duration: 0.5,
    ease: "cubic-bezier(0.25, 0.46, 0.45, 0.94)"
  });
  timelines.push(tlPlate);

  // Caption block rise-in starting 120ms after
  captionBlock.position.y -= 0.4;
  const tlCaption = gsap.to(captionBlock.position, {
    y: "-=0",
    yTo: -plateHeight / 2 + 0.5,
    duration: 0.7,
    delay: 0.12,
    ease: "power3.out"
  });
  timelines.push(tlCaption);

  // 5. PRIMITIVES & LIFE CYCLE
  const activePrimitives = [];
  const appliedSpecs = config.cinematicPrimitives || [{ name: 'parallax-scroll', params: { intensity: 0.35 } }];
  appliedSpecs.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params);
      if (res) activePrimitives.push(res);
    }
  });

  group.userData = {
    cleanup() {
      timelines.forEach(t => t.kill());
      activePrimitives.forEach(p => p.cleanup && p.cleanup());
      geometry.dispose();
      material.dispose();
      bgGeom.dispose();
      bgMat.dispose();
      barGeom.dispose();
      barMat.dispose();
    }
  };

  return group;
}
